// function toggleFeature(feature, enabled)
// Agar feature nahi: "No feature specified"
// Agar enabled boolean nahi: "Invalid flag"
// Warna { feature, enabled } return karo

solution:
function toggleFeature(feature, enabled) {
  if (!feature) return "No feature specified"
  if (typeof enabled !== "boolean") return "Invalid flag"
  return { feature, enabled }
}
